        &lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#ILLUMINATION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Illumination&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#RESTAURATION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Restauration&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#REVELATION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;R&#233;v&#233;lation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#TACTIQUE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Tactique&lt;/a&gt;&lt;/td&gt;
